<script>
(() => {
 const api='api_jenny_customer_exclusion.php', previewApi='api_jenny_cleanup_preview.php';
 const search=document.getElementById('pfCaSearch'), results=document.getElementById('pfCaResults'), message=document.getElementById('pfCaMessage'), summary=document.getElementById('pfCaCustomerSummary'), scope=document.getElementById('pfCaScope'), orders=document.getElementById('pfCaOrders'), archives=document.getElementById('pfCaArchives'), actions=document.getElementById('pfCaActions'), hide=document.getElementById('pfCaHide'), restore=document.getElementById('pfCaRestore'), dialog=document.getElementById('pfCaDialog');
 if(!search||!results||!message||!scope||!orders||!archives||!actions||!hide||!restore||!dialog)return;
 let selectedId=0, selectedName='', currentStatus='inactive', archiveManaged=true, visibleOrders=0, archivedOrders=0, csrf=document.querySelector('meta[name="csrf-token"]')?.content||'', ready=false, pendingAction='', archivePreviewToken='', timer;
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const dispositionLabel=value=>{const c=String(value||'').toLowerCase();if(c.startsWith('protected_'))return c.includes('ambiguous')?'Protected — shared reference':'Protected — retained';if(c.startsWith('uncertain_'))return 'Review required — record retained';return c?c.replaceAll('_',' '):'Record retained';};
 const setMessage=(text,kind='')=>{message.className='pf-box'+(kind?' '+kind:'');message.textContent=text;};
 function resultCounts(result){return `Total orders found: ${Number(result.total_orders_found)||0}; already archived: ${Number(result.already_archived_count)||0}; newly archived: ${Number(result.newly_archived_count)||0}; remaining visible: ${Number(result.remaining_visible_count)||0}; failed: ${Number(result.failed_count)||0}${result.failed_reason?`; reason: ${result.failed_reason}`:''}.`;}
 async function jsonFetch(url,options={}){const r=await fetch(url,{credentials:'same-origin',cache:'no-store',...options});let body;try{body=await r.json()}catch{throw new Error(`Server returned unreadable JSON (HTTP ${r.status}).`)}if(!r.ok||body.success!==true){const extra=body.total_orders_found!=null?` ${resultCounts(body)}`:'';throw new Error((body.error||`Request failed (HTTP ${r.status}).`)+extra);}return body;}
 function clearSelection(){selectedId=0;selectedName='';ready=false;archivePreviewToken='';actions.hidden=true;hide.disabled=true;restore.disabled=true;summary.hidden=true;}
 async function findCustomer(){clearTimeout(timer);const term=search.value.trim();timer=setTimeout(async()=>{clearSelection();if(term===''||(term.length<2&&!/^\d+$/.test(term))){results.innerHTML='<p class="pf-empty">Enter a name, email, phone number, or customer ID. Archive actions stay hidden until you select one customer.</p>';return;}results.innerHTML='<p class="pf-empty">Searching…</p>';try{const data=await jsonFetch(`${api}?search=${encodeURIComponent(term)}`);const rows=data.customers||[];results.innerHTML=`<table class="pf-table"><thead><tr><th>Customer</th><th>Email</th><th>Phone</th><th>Customer ID</th><th>Total orders</th><th>Visible orders</th><th>Archived orders</th><th>Archive status</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.email||'—')}</td><td>${esc(c.phone||'—')}</td><td>${Number(c.customer_id)}</td><td>${Number(c.total_orders)||0}</td><td>${Number(c.visible_orders)||0}</td><td>${Number(c.archived_orders)||0}</td><td>${esc(c.archive_status||'Visible')}</td><td><button type="button" class="pf-button pf-primary" data-select="${Number(c.customer_id)}" data-name="${esc(c.name)}">Select</button></td></tr>`).join('')||'<tr><td colspan="8" class="pf-empty">No matching customers.</td></tr>'}</tbody></table>`;results.querySelectorAll('[data-select]').forEach(button=>button.addEventListener('click',()=>{selectedId=Number(button.dataset.select)||0;selectedName=button.dataset.name||'';loadPreview();}));setMessage(rows.length?'Select one customer to review orders before using Hide All Orders or Restore All Orders.':'No matching customers.');}catch(e){results.innerHTML='<p class="pf-empty">Search unavailable.</p>';setMessage(e.message,'error');}},220);}
 async function loadArchiveList(){try{const data=await jsonFetch(`${api}?list=1`);const rows=data.archives||[];archives.innerHTML=`<table class="pf-table"><thead><tr><th>Customer</th><th>Customer ID</th><th>Hidden orders</th><th>Date archived</th><th>Archived by</th><th>Status</th><th>Reference</th><th>Action</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.first_name)} ${esc(r.last_name)}</td><td>${Number(r.customer_id)}</td><td>${r.status==='active'?Number(r.total_orders)||0:0}</td><td>${esc(r.archived_at)}</td><td>${esc(r.archived_by_name||`User #${r.archived_by}`)}</td><td>${esc(r.status)}${r.archive_managed?'':' (managed elsewhere)'}</td><td>${esc(r.archive_reference_id||'—')}</td><td>${r.status==='active'&&r.archive_managed?`<button type="button" class="pf-button pf-restore" data-restore="${Number(r.customer_id)}" data-name="${esc(r.first_name)} ${esc(r.last_name)}">Restore</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="8" class="pf-empty">No customers are currently archived.</td></tr>'}</tbody></table>`;archives.querySelectorAll('[data-restore]').forEach(b=>b.addEventListener('click',async()=>{selectedId=Number(b.dataset.restore)||0;selectedName=b.dataset.name||'';await loadPreview();openDialog('restore');}));}catch(e){archives.innerHTML=`<p class="pf-box error">Archive list unavailable: ${esc(e.message)}</p>`;}}
 async function loadPreview(){if(selectedId<1)return;ready=false;actions.hidden=true;hide.disabled=true;restore.disabled=true;summary.hidden=true;scope.innerHTML='<p class="pf-empty">Loading exact counts…</p>';orders.innerHTML='<p class="pf-empty">Loading orders…</p>';setMessage('Verifying the selected customer and loading current records…');try{const [control,preview]=await Promise.all([jsonFetch(`${api}?customer_id=${selectedId}`),jsonFetch(`${previewApi}?customer_id=${selectedId}`)]);if(control.customer_id!==selectedId||preview.target?.customer_id!==selectedId||preview.database?.name!=='u618446170_printflow'||!control.preview_token)throw new Error('The live preview did not match the selected customer.');csrf=control.csrf_token||csrf;archivePreviewToken=control.preview_token;currentStatus=control.exclusion?.status||'inactive';archiveManaged=control.archive_managed!==false;visibleOrders=Number(control.visible_orders)||0;archivedOrders=Number(control.archived_orders)||0;const c=control.customer||{};selectedName=`${c.first_name||''} ${c.last_name||''}`.trim()||selectedName;summary.hidden=false;summary.innerHTML=`<strong>${esc(selectedName)} (#${control.customer_id})</strong> · ${esc(c.email||'')} · ${esc(c.phone||c.contact_number||'')} · Total orders: ${Number(control.total_orders??control.orders_currently_owned)||0} · Visible orders: ${visibleOrders} · Archived orders: ${archivedOrders} · <span class="pf-chip">${esc(currentStatus==='active'?'Archived':'Visible')}${archiveManaged?'':' · managed elsewhere'}</span>${control.archive_reference_id?` · Reference: <code>${esc(control.archive_reference_id)}</code>`:''}`;
 const groups=Object.entries(preview.records||{});scope.innerHTML=`<table class="pf-table pf-scope-table"><thead><tr><th>Record group</th><th>Count</th><th>Disposition</th></tr></thead><tbody>${groups.map(([name,item])=>`<tr><td>${esc(name.replaceAll('_',' '))}</td><td>${Number(item.count)||0}</td><td class="pf-disposition" title="${esc(item.classification||'classified by live preview')}">${esc(dispositionLabel(item.classification))}</td></tr>`).join('')||'<tr><td colspan="3">No related record counts returned.</td></tr>'}</tbody></table>`;
 const rows=control.orders||[];orders.innerHTML=`<table class="pf-table"><thead><tr><th>Order code</th><th>Order date</th><th>Order status</th><th>Archive status</th></tr></thead><tbody>${rows.map(o=>`<tr><td>${esc(o.order_code)}</td><td>${esc(o.order_date)}</td><td>${esc(o.status)}</td><td>${esc(o.archive_status)}</td></tr>`).join('')||'<tr><td colspan="4" class="pf-empty">No current orders found.</td></tr>'}</tbody></table>`;
 ready=true;actions.hidden=false;hide.disabled=!archiveManaged;restore.disabled=!archiveManaged||(currentStatus!=='active'&&archivedOrders<1);setMessage(archiveManaged?`Verified live database ${preview.database.name}; preview ${preview.diagnostic_version}. Customer #${selectedId}: ${Number(control.total_orders??control.orders_currently_owned)||0} total, ${visibleOrders} visible, ${archivedOrders} archived. No transaction records were changed.`:'A separate customer exclusion is already present. This archive will not overwrite or restore it; actions are disabled.',archiveManaged?'success':'error');await loadArchiveList();}catch(e){ready=false;actions.hidden=true;setMessage(`Preview unavailable: ${e.message}. Archive actions are disabled.`,'error');}}
 function openDialog(action){if(!ready||selectedId<1||!archiveManaged)return;pendingAction=action;const label=`${selectedName||'the selected customer'} (#${selectedId})`;document.getElementById('pfCaDialogTitle').textContent=action==='activate'?'Hide All Orders?':'Restore All Orders?';document.getElementById('pfCaDialogText').textContent=action==='activate'?`This will hide every eligible order for ${label} from Admin, Staff, Customer, reports, dashboards, search, notifications, payments, and order lists. Orders that are already archived stay archived. It does not delete database records or change payment, inventory, file, message, webhook, receipt, or account records. An Admin can restore them later.`:`This will restore orders for ${label}. It changes only that customer's archive visibility. It does not edit orders, payments, inventory, files, messages, webhooks, receipts, or other customers.`;dialog.showModal();}
 document.getElementById('pfCaDialogCancel').addEventListener('click',()=>dialog.close());document.getElementById('pfCaDialogConfirm').addEventListener('click',async()=>{if(!ready||!pendingAction||!archivePreviewToken||selectedId<1)return;const action=pendingAction;dialog.close();hide.disabled=true;restore.disabled=true;setMessage('Saving the reversible customer archive…');try{const result=await jsonFetch(api,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({action,customer_id:selectedId,csrf_token:csrf,preview_token:archivePreviewToken})});archivePreviewToken='';await loadPreview();setMessage(`${action==='activate'?'Hide All':'Restore All'} complete for ${result.customer_name||selectedName} (#${result.customer_id||selectedId}). ${resultCounts(result)} Archive reference: ${result.archive_reference_id||'retained'}.`,'success');}catch(e){archivePreviewToken='';setMessage(`Archive action failed: ${e.message}`,'error');if(selectedId>0)await loadPreview();}});
 search.addEventListener('input',findCustomer);hide.addEventListener('click',()=>openDialog('activate'));restore.addEventListener('click',()=>openDialog('restore'));loadArchiveList();
})();
</script>
<details class="pf-archive-card"><summary style="font-weight:700;cursor:pointer">Other order archive tools</summary><p class="pf-muted">The separately maintained exact-order manifest tool remains available.</p><p><a href="<?= htmlspecialchars($basePath, ENT_QUOTES, 'UTF-8') ?>/admin/archived_orders_manifest.php">Open exact-order manifest archive</a></p></details>
